def seed(db):
    state_cache = {}
    district_cache = {}
    total_states = 0
    total_districts = 0
    total_pincodes = 0

    for state_name, districts in LOCATION_DATA.items():
        state = db.query(State).filter_by(name=state_name).first()
        if not state:
            state = State(name=state_name, is_active=True)
            db.add(state)
            db.flush()
            total_states += 1
        state_cache[state_name] = state.id

        for district_name, pincodes in districts:
            key = f"{state.id}:{district_name}"
            district = db.query(District).filter_by(state_id=state.id, name=district_name).first()
            if not district:
                district = District(state_id=state.id, name=district_name)
                db.add(district)
                db.flush()
                total_districts += 1
            district_cache[key] = district.id

            for pincode_val, office_name in pincodes:
                existing = db.query(Pincode).filter_by(pincode=pincode_val).first()
                if not existing:
                    db.add(Pincode(
                        pincode=pincode_val,
                        post_office=office_name,
                        district_id=district.id,
                        state_id=state.id,
                        is_active=True,
                    ))
                    total_pincodes += 1

        db.commit()
        print(f"  ✓ {state_name}: {len(districts)} districts")

    print(f"\nSeeded: {total_states} new states, {total_districts} new districts, {total_pincodes} new pincodes")


if __name__ == "__main__":
    db = SessionLocal()
    try:
        print("Seeding India location data...")
        seed(db)
    finally:
        db.close()
